import { daysBetween } from './dates.js';
import { balanceDue } from './payments.js';
import { roundCents } from './money.js';

/**
 * Get invoices that are overdue.
 * @param {Array<{ number?: string, status: string, dueDate: string, lines: Array }>} invoices
 * @param {string} asOf - Date in YYYY-MM-DD format
 * @returns {Array<{ number: string, customerId: string, dueDate: string, daysOverdue: number, due: number }>}
 */
export function overdueInvoices(invoices, asOf) {
  return invoices
    .filter((inv) => {
      if (inv.status !== 'issued' && inv.status !== 'partially_paid') return false;
      if (daysBetween(inv.dueDate, asOf) <= 0) return false;
      return true;
    })
    .map((inv) => {
      const daysOverdue = daysBetween(inv.dueDate, asOf);
      const due = balanceDue(inv);
      return {
        number: inv.number,
        customerId: inv.customerId,
        dueDate: inv.dueDate,
        daysOverdue,
        due,
      };
    })
    .sort((a, b) => b.daysOverdue - a.daysOverdue);
}

/**
 * Get a summary of VAT by rate across invoices.
 * @param {Array<{ status: string, lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }> }>} invoices
 * @returns {Array<{ rate: number, base: number, vat: number }>}
 */
export function vatSummary(invoices) {
  const vatMap = new Map();

  invoices.forEach((inv) => {
    if (inv.status !== 'issued' && inv.status !== 'partially_paid' && inv.status !== 'paid') return;

    inv.lines.forEach((line) => {
      const lineTotal = line.qty * line.unitPrice;
      const discountAmount = roundCents(lineTotal * (line.discountPercent ?? 0) / 100);
      const lineBase = lineTotal - discountAmount;
      const lineVat = roundCents(lineBase * line.vatRate / 100);

      if (!vatMap.has(line.vatRate)) {
        vatMap.set(line.vatRate, { base: 0, vat: 0 });
      }

      const current = vatMap.get(line.vatRate);
      current.base += lineBase;
      current.vat += lineVat;
    });
  });

  return Array.from(vatMap.entries())
    .map(([rate, { base, vat }]) => ({ rate, base, vat }))
    .sort((a, b) => b.rate - a.rate);
}

/**
 * Calculate late fee for an invoice: 0.04% per day overdue.
 * @param {{ status: string, dueDate: string, lines: Array, payments?: Array }} invoice
 * @param {string} asOf - Date in YYYY-MM-DD format
 * @returns {number} Late fee in cents, 0 if not overdue
 */
export function lateFee(invoice, asOf) {
  if (invoice.status === 'draft' || invoice.status === 'paid') {
    return 0;
  }

  const daysOverdue = daysBetween(invoice.dueDate, asOf);
  if (daysOverdue <= 0) {
    return 0;
  }

  const due = balanceDue(invoice);
  return roundCents(due * daysOverdue * 0.0004);
}

