/**
 * Calculate late fee for an invoice: 0.04% per day overdue.
 * @param {{ status: string, dueDate: string, lines: Array, payments?: Array }} invoice
 * @param {string} asOf - Date in YYYY-MM-DD format
 * @returns {number} Late fee in cents, 0 if not overdue
 */
export function lateFee(invoice, asOf) {
  if (invoice.status === 'draft' || invoice.status === 'paid') {
    return 0;
  }

  const daysOverdue = daysBetween(invoice.dueDate, asOf);
  if (daysOverdue <= 0) {
    return 0;
  }

  const due = balanceDue(invoice);
  return roundCents(due * daysOverdue * 0.0004);
}

/**
 * Get dashboard statistics for invoices.
 * @param {Array<{ customerId: string, status: string, dueDate: string, lines: Array, payments?: Array }>} invoices
 * @param {string} asOf - Date in YYYY-MM-DD format
 * @returns {{ counts: { draft: number, issued: number, partially_paid: number, paid: number }, outstanding: number, overdue: { count: number, amount: number }, topCustomers: Array<{ customerId: string, due: number }> }}
 */
export function dashboard(invoices, asOf) {
  const counts = {
    draft: 0,
    issued: 0,
    partially_paid: 0,
    paid: 0,
  };

  let outstanding = 0;
  const customerDueMap = new Map();

  invoices.forEach((inv) => {
    counts[inv.status]++;

    if (inv.status === 'issued' || inv.status === 'partially_paid') {
      const due = balanceDue(inv);
      outstanding += due;

      if (!customerDueMap.has(inv.customerId)) {
        customerDueMap.set(inv.customerId, 0);
      }
      customerDueMap.set(inv.customerId, customerDueMap.get(inv.customerId) + due);
    }
  });

  const overdue = overdueInvoices(invoices, asOf);
  const overdueSummary = {
    count: overdue.length,
    amount: overdue.reduce((sum, inv) => sum + inv.due, 0),
  };

  const topCustomers = Array.from(customerDueMap.entries())
    .map(([customerId, due]) => ({ customerId, due }))
    .sort((a, b) => b.due - a.due)
    .slice(0, 3);

  return {
    counts,
    outstanding,
    overdue: overdueSummary,
    topCustomers,
  };
}

