  const issued1 = issueInvoice(inv1, []).value;
  const issued2 = issueInvoice(inv2, ['INV-2026-0001']).value;
  const totals1 = invoiceTotals(issued1);
  const totals2 = invoiceTotals(issued2);

  const fee1 = lateFee(issued1, '2026-10-20');
  const fee2 = lateFee(issued2, '2026-10-20');

  assert.ok(fee2 > fee1);
  assert.equal(fee2, Math.round(totals2.total * 5 * 0.0004));
  assert.equal(fee1, Math.round(totals1.total * 5 * 0.0004));
});

test('lateFee with partial payment affects calculation', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
    terms: 'NET14',
  }).value;

  const issued = issueInvoice(inv, []).value;
  const totals = invoiceTotals(issued);
  const partial1 = recordPayment(issued, { amount: 40000, date: '2026-10-20' }).value;

  const fee = lateFee(partial1, '2026-10-25');
  const balance = totals.total - 40000;
  const daysOverdue = 10;
  const expected = Math.round(balance * daysOverdue * 0.0004);
  assert.equal(fee, expected);
});

test('lateFee rounding works correctly', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'STICKER', qty: 5 }],
    terms: 'NET14',
  }).value;

  const issued = issueInvoice(inv, []).value;

  const result = lateFee(issued, '2026-10-20');
  const balance = 50 * 5;
  const daysOverdue = 5;
  const expected = Math.round(balance * daysOverdue * 0.0004);
  assert.ok(Number.isInteger(result));
  assert.equal(result, expected);
});

